// STEP 1: Extract base data for AI and assembly
const baseJson = $('When Executed by Another Workflow').first().json;
const req = baseJson.request_json;
const usernames = $input.first().json.usernames;

// Determine endpoint type
const endpoint = baseJson.endpoint;
const isStyleEndpoint = endpoint.includes('style');
const isVid1Single = endpoint === '/create-video-vid-1';
const isMultiClip = endpoint.includes('vid-1.2') || endpoint.includes('vid-1.3') || endpoint.includes('vid-1.4') || endpoint.includes('vid-1.5');

// Determine media type
let mediaType = 'video';
if (isStyleEndpoint) mediaType = 'image';

// Count clips
let numClips = 1;
if (isMultiClip && req.clips?.length > 0) numClips = req.clips.length;

// Get description for search terms
const mainDescription = baseJson.description || 'motivational content';

// Get original captions
const originalCaptions = req.captions?.map(c => c.text) || [];

// Get clip descriptions
const clipDescriptions = req.clips?.map(c => c.description) || [mainDescription];

return [{
  json: {
    // For AI Agent
    forAI: {
      description: mainDescription,
      numVariants: usernames.length,
      numClips: numClips,
      transcriptionRequired: baseJson.transcription || false,
      audioUrl: req.audioUrl,
      originalCaptions: originalCaptions,
      originalMainCaption: baseJson.caption,
      originalClipDescriptions: clipDescriptions,
      mediaType: mediaType
    },
    // For Assembly
    baseStructure: {
      endpoint, audioUrl: req.audioUrl, instagramUrl: req.instagramUrl,
      original: req.original, quote: req.quote, author: req.author,
      duration: req.duration, overlay: req.overlay,
      description: baseJson.description, niche: baseJson.niche,
      transcription: baseJson.transcription, caption: baseJson.caption,
      imageUrl: req.imageUrl, videoUrl: req.videoUrl,
      clips: req.clips?.map(c => ({start: c.start, duration: c.duration, volume: c.volume, begin: c.begin})) || [],
      captions: req.captions?.map(c => ({text: c.text, start: c.start, duration: c.duration})) || []
    },
    endpointType: { isStyleEndpoint, isVid1Single, isMultiClip, mediaType },
    usernames: usernames
  }
}];

parameters.text:
=You generate search terms and text rewrites for video variants.

## INPUT:
- Description: {{ $json.forAI.description }}
- Variants needed: {{ $json.forAI.numVariants }}
- Clips per variant: {{ $json.forAI.numClips }}
- Media type: {{ $json.forAI.mediaType }}
- Transcription required: {{ $json.forAI.transcriptionRequired }}
- Audio URL: {{ $json.forAI.audioUrl }}
- Original captions: {{ JSON.stringify($json.forAI.originalCaptions) }}
- Original main caption: {{ $json.forAI.originalMainCaption }}
- Original clip descriptions: {{ JSON.stringify($json.forAI.originalClipDescriptions) }}

## TASKS:
1. Generate 2-3 Pexels search terms based on description themes
2. IF transcriptionRequired=true: Call Transcription tool with audioUrl, then generate timing adjustments
3. Generate rewrites for EACH variant (keep same meaning, vary wording)

## OUTPUT FORMAT (JSON only, no markdown):
{
  "searchTerms": ["term1", "term2"],
  "timingAdjustments": null,
  "variants": [
    {
      "captionAlts": ["rewrite of caption 1", "rewrite of caption 2"],
      "description": "rewritten description",
      "mainCaption": "rewritten main caption with hashtags",
      "clipDescriptions": ["clip 1 desc", "clip 2 desc"]
    }
  ]
}

## RULES:
- searchTerms: Extract key themes (travel, success, fitness, etc.)
- Each variant needs DIFFERENT rewrites but SAME meaning
- clipDescriptions array must have exactly {{ $json.forAI.numClips }} items per variant
- If no captions, captionAlts = []
- Return ONLY valid JSON

