// Parse AI output
const raw = $json.output;
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let aiOutput;
try { aiOutput = JSON.parse(cleaned); } catch (e) { throw new Error('AI parse error: ' + e.message); }

const extractData = $('Extract Base Data').first().json;
const { forAI } = extractData;

// Prepare for Pexels fetch
return [{
  json: {
    searchTerms: aiOutput.searchTerms || ['motivational'],
    mediaType: forAI.mediaType,
    numNeeded: forAI.numClips * forAI.numVariants + 5,
    aiOutput: aiOutput,
    extractData: extractData
  }
}];

// Extract image URLs from Pexels response
const photos = $json.photos || [];
const urls = photos.map(p => p.src?.large2x || p.src?.large || p.src?.original);
const parseData = $('Parse AI Output').first().json;
return [{ json: { mediaUrls: urls, ...parseData } }];

// Extract video URLs from Pexels response
const videos = $json.videos || [];
const urls = videos.map(v => {
  const files = v.video_files || [];
  const hd = files.find(f => f.quality === 'hd') || files[0];
  return hd?.link;
}).filter(Boolean);
const parseData = $('Parse AI Output').first().json;
return [{ json: { mediaUrls: urls, ...parseData } }];

// STEP 4: Assemble final variants
const { mediaUrls, aiOutput, extractData } = $json;
const { baseStructure, endpointType, usernames } = extractData;
const numClips = extractData.forAI.numClips;

// Distribute URLs across variants (with reuse if needed)
function getUrl(variantIdx, clipIdx) {
  const idx = (variantIdx * numClips + clipIdx) % mediaUrls.length;
  return mediaUrls[idx] || mediaUrls[0];
}

const variants = usernames.map((username, vIdx) => {
  const variantData = aiOutput.variants?.[vIdx] || aiOutput.variants?.[0] || {};

  const variant = {
    endpoint: baseStructure.endpoint,
    request_json: {
      audioUrl: baseStructure.audioUrl,
      original: baseStructure.original,
      watermark: '@' + username.replace('@', '')
    },
    caption: variantData.mainCaption || baseStructure.caption,
    description: variantData.description || baseStructure.description,
    niche: baseStructure.niche,
    transcription: baseStructure.transcription
  };

  if (baseStructure.quote) variant.request_json.quote = baseStructure.quote;
  if (baseStructure.author) variant.request_json.author = baseStructure.author;
  if (baseStructure.duration) variant.request_json.duration = baseStructure.duration;
  if (baseStructure.overlay !== undefined) variant.request_json.overlay = baseStructure.overlay;

  // Handle media based on endpoint type
  if (endpointType.isStyleEndpoint) {
    variant.request_json.imageUrl = getUrl(vIdx, 0);
    variant.request_json.imageDescription = variantData.clipDescriptions?.[0] || baseStructure.description;
  } else if (endpointType.isVid1Single) {
    variant.request_json.videoUrl = getUrl(vIdx, 0);
    variant.request_json.videoDescription = variantData.clipDescriptions?.[0] || baseStructure.description;
  } else if (endpointType.isMultiClip) {
    variant.request_json.clips = baseStructure.clips.map((clipTiming, cIdx) => ({
      ...clipTiming,
      videoUrl: getUrl(vIdx, cIdx),
      description: variantData.clipDescriptions?.[cIdx] || 'Video clip'
    }));
  }

  // Add captions with alts
  if (baseStructure.captions?.length > 0) {
    variant.request_json.captions = baseStructure.captions.map((c, i) => ({
      ...c,
      alt: variantData.captionAlts?.[i]
    }));
  }

  // Apply timing adjustments if transcription was processed
  if (aiOutput.timingAdjustments && variant.request_json.clips) {
    aiOutput.timingAdjustments.forEach((adj, i) => {
      if (variant.request_json.clips[i] && adj) {
        if (adj.start !== undefined) variant.request_json.clips[i].start = adj.start;
        if (adj.duration !== undefined) variant.request_json.clips[i].duration = adj.duration;
      }
    });
  }

  return variant;
});

return variants.map(v => ({ json: v }));

